/* The $C700 flag block, GameData.c700[FLAG_*]: the bytes with a
 * name. The save's keys (assets/data/flag_names.json) are not these:
 * a byte named there only by the routine that touches it gets its
 * name here (FLAG_NAMES in the generator), and the event objects'
 * own bytes are FLAG_EVENT_SLOTS + the event. */
#define FLAG_EVENT_SLOTS                            0x10   /* event n's own byte is c700[FLAG_EVENT_SLOTS + n] (ObjType_Events: event_flags + n) */
